import Foundation

struct SM64BlackSmokeMarioObjectEffectRecord: Equatable, Sendable { let objectID: SM64ObjectID; let output: SM64BlackSmokeMarioOutput }
struct SM64FlameMarioObjectEffectRecord: Equatable, Sendable { let objectID: SM64ObjectID; let output: SM64FlameMarioOutput; let spawnedSmoke: SM64ObjectID? }

final class SM64BlackSmokeMarioObjectBridge {
    static let defaultBehaviorIdentity: UInt64 = 0x6268_765F_626D31
